def ckpt_path(root, key):
    return "%s/inputs/%s/ckpt_last.pt" % (root, key)


def build_runs(root=ROOT, py=PY, cache=CACHE, ceiling=False):
    """The 10 runs in the order of record (control r1 at m = 0 first, then m = 0, 1, 2 with rows e, f, b): list of dicts with name, argv, outdir, ckpt key, grid key, preroll."""
    P = paths(root)
    tracks = cache + "/native_tracks.pt"
    runs = []
    order = [(m, x) for m in MODEL_SEEDS for x in CEILING_ROWS] if ceiling else [(0, x) for x in CONTROL_FIRST] + [(m, x) for m in MODEL_SEEDS for x in ROW_ORDER]
    for m, letter in order:
        r = READER_SEED[m]
        if True:
            rname, fam, form, accg, every, gkey, pre, fc = ROWS[letter]
            arm = "%s_s%d" % (rname, m)
            out = "%s/%s" % (P["runs"], arm)
            tag = "%s_m10_causal_heads" % arm
            ck = "%s_s%d" % (fam, m)
            extra = []
            if form in ("RR", "RRe", "RRc"):
                extra += ["--reader", "%s/inputs/lr16/TK16_s%d/ckpt_last.pt" % (root, r)]
            if every is not None:
                extra += ["--rule-every", str(every)]
            extra += ["--kappa-max", "0.2", "--acc-gain", str(accg), "--path-exec"]
            extra += ["--readout", "causal_g", "--readout-log", "%s/ticks/readout_log_%s.json" % (out, arm)]
            if pre is not None:
                extra += ["--preroll-steps", str(pre)]
            if form in ("RR", "RRe", "RRc"):
                extra += ["--qmap", "%s/inputs/qmap/QMAP_LR16_s%d_q50.json" % (root, r)]
            if form != "R0":
                extra += ["--rule-log", "%s/ticks/rule_log_%s.npz" % (out, arm)]
            wkey = "wrapper_pre" if pre is not None else "wrapper"
            fcx = []
            if form in ("RRe", "RRc"):
                wkey = "wrapper_et"
            if fc is not None:
                fcx = ["--closing-table", P["head_table" if fc == "head" else "zero_table"]]
            argv = [py, P[wkey]] + fcx + ["--tree", P["tree"], "--form", form] + extra + [
                "run", "--ckpt", ckpt_path(root, ck), "--tag", tag, "--tracks", tracks,
                "--eval-cache", cache, "--eval-grid", P[gkey], "--eval-join", P["join"],
                "--out-dir", out, "--replan-steps", "10", "--nav", "deadreckon", "--scene", "logged",
                "--schedule", "periodic", "--limit", "causal", "--dump-ticks", out + "/ticks",
                "--dump-heads", "--no-analyze", "--device", "cuda",
            ]
            runs.append({"m": m, "letter": letter, "name": rname, "arm": arm, "tag": tag, "ckpt": ck,
                         "grid": gkey, "preroll": pre, "outdir": out, "argv": argv, "wrapper": wkey, "fc": None, "table": fc})
    return runs


