# ---- probes (module level so the tests can replace them) -------------------------------------------------------------
def free_disk_gb(path):
    return shutil.disk_usage(path).free / 1073741824.0


def free_vram_mib():
    """Free VRAM of GPU 0 in MiB, or None when unreadable (the caller stops)."""
    try:
        o = subprocess.run(["nvidia-smi", "--query-gpu=memory.free", "--format=csv,noheader,nounits"],
                           capture_output=True, text=True, encoding="utf-8", timeout=60)
        return float(o.stdout.strip().splitlines()[0])
    except Exception:
        return None


def execute(argv, env, log_path, timeout_s):
    """Run one job at below-normal priority with affinity 0xFF; returns the exit code (124 on timeout)."""
    flags = 0
    if os.name == "nt":
        flags = 0x00004000 | 0x08000000  # BELOW_NORMAL_PRIORITY_CLASS | CREATE_NO_WINDOW
    with open(log_path, "ab") as lf:
        p = subprocess.Popen(argv, env=env, stdout=lf, stderr=subprocess.STDOUT, creationflags=flags)
        if os.name == "nt":
            try:
                import ctypes
                from ctypes import wintypes
                ctypes.windll.kernel32.SetProcessAffinityMask(wintypes.HANDLE(int(p._handle)), 0xFF)
            except Exception:
                pass
        try:
            return p.wait(timeout=timeout_s)
        except subprocess.TimeoutExpired:
            p.kill()
            p.wait()
            return 124


def sha256_file(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(1 << 20), b""):
            h.update(b)
    return h.hexdigest()


def grid_clip_count(path):
    g = json.load(open(path, encoding="utf-8"))
    return len(g["order"])


# ---- card ADD152 controls t2 / t3: a zero-table run equals its partner array for array -------------------------------------------------------------
PARTNER = {"H_RQ50KVz": "H_RQ50KE1", "H_RQ50KVz_P30": "H_RQ50KE1_P30"}


def _npz_cmp(pa, pb, need_all=True):
    """Arrays of npz pa (partner) against npz pb (new run). Numeric arrays: equal exactly (NaN equal to NaN). -> (ok, n_numeric, list of differing or missing keys,
    list of non-numeric keys that differ, reported only)."""
    import numpy as np
    bad, other, n = [], [], 0
    with np.load(pa, allow_pickle=True) as A, np.load(pb, allow_pickle=True) as B:
        for k in A.files:
            if k not in B.files:
                if need_all:
                    bad.append("missing:" + k)
                continue
            x, y = A[k], B[k]
            if x.dtype.kind in "biufc" and y.dtype.kind in "biufc":
                n += 1
                if x.shape != y.shape or not np.array_equal(x, y, equal_nan=x.dtype.kind in "fc"):
                    bad.append(k)
            elif not (x.shape == y.shape and np.array_equal(x, y)):
                other.append(k)
    return not bad, n, bad, other


def compare_partner(root, r):
    """Control t2 / t3 of card ADD152: every dump file of the zero-table run against the partner's, then the rule log and the later-look log (common keys:
    the partner's keys must all be there). Writes CONTROL_ZERO.json in the run folder; -> (PASS, summary)."""
    P = paths(root)
    part = "%s_s%d" % (PARTNER[r["name"]], r["m"])
    pdir, ndir = "%s/%s" % (P["runs"], part), r["outdir"]
    pd, nd = "%s/dump_%s_m10_causal_heads" % (pdir, part), "%s/dump_%s" % (ndir, r["tag"])
    files = sorted(x for x in os.listdir(pd) if x.startswith("ep") and x.endswith(".npz"))
    res = {"partner": part, "dump_files": len(files), "dump_bad": [], "dump_numeric_arrays": 0, "non_numeric_differ": {}}
    for x in files:
        if not os.path.isfile(os.path.join(nd, x)):
            res["dump_bad"].append([x, "missing"])
            continue
        ok, n, bad, other = _npz_cmp(os.path.join(pd, x), os.path.join(nd, x))
        res["dump_numeric_arrays"] += n
        if not ok:
            res["dump_bad"].append([x, bad[:8]])
        if other:
            res["non_numeric_differ"][x] = other
    logs = {}
    for kind in ("rule_log_%s.npz", "rule_log_mid_%s.npz"):
        a, b = "%s/ticks/%s" % (pdir, kind % part), "%s/ticks/%s" % (ndir, kind % r["arm"])
        if not (os.path.isfile(a) and os.path.isfile(b)):
            logs[kind % "X"] = {"PASS": False, "why": "missing file"}
            continue
        ok, n, bad, other = _npz_cmp(a, b)
        logs[kind % "X"] = {"PASS": ok, "numeric_arrays": n, "bad": bad, "non_numeric_differ": other}
    res["logs"] = logs
    res["PASS"] = bool(files) and not res["dump_bad"] and res["dump_numeric_arrays"] > 0 and all(v["PASS"] for v in logs.values())
    with open(ndir + "/CONTROL_ZERO.json", "w", encoding="utf-8") as f:
        json.dump(res, f, indent=1)
    return res["PASS"], res


# ---- driver ------------------------------------------------------------------------------------------------------------
class Stop(Exception):
    pass


def now():
    return time.strftime("%Y-%m-%dT%H:%M:%S")


def write_stop(P, why):
    try:
        with open(P["stop"], "w", encoding="utf-8") as f:
            f.write("%s %s\n" % (now(), why))
    except OSError:
        pass
    print("STOP", why, flush=True)


def preflight(root, runs, check_sha=True):
    P = paths(root)
    need = set()
    for r in runs:
        need.add(ckpt_path(root, r["ckpt"]))
        for i, a in enumerate(r["argv"]):
            if a in ("--reader", "--qmap"):
                need.add(r["argv"][i + 1])
    need.update([P["wrapper"], P["wrapper_pre"], P["wrapper_et"], P["head_table"], P["zero_table"], P["tool"], P["grid141"], P["gridp30"], P["join"], TRACKS if root == ROOT else None])
    need.discard(None)
    for p in sorted(need):
        if not os.path.isfile(p):
            raise Stop("MISSING-INPUT %s" % p)
    if check_sha:
        for k, want in CKPT_SHA.items():
            got = sha256_file(ckpt_path(root, k))
            if got != want:
                raise Stop("CKPT-SHA %s %s" % (k, got))
        for k in ("wrapper", "wrapper_pre", "wrapper_et", "head_table", "zero_table", "tool", "grid141", "gridp30", "join"):
            got = sha256_file(P[k])
            if got != PINNED_SHA[k]:
                raise Stop("PINNED-SHA %s %s" % (k, got))


def run_one(root, r, env):
    P = paths(root)
    out = r["outdir"]
    done = out + "/RUN_DONE.json"
    if os.path.exists(done):
        print("skip (done)", r["arm"], flush=True)
        return
    if os.path.exists(P["stop"]):
        raise Stop("STOP-FILE-PRESENT")
    if os.path.exists(out):
        raise Stop("OUTPUT-EXISTS-WITHOUT-DONE %s" % out)
    fd = free_disk_gb(root)
    if fd < MIN_FREE_DISK_GB:
        raise Stop("DISK-LOW %.2f GB" % fd)
    vr = free_vram_mib()
    if vr is None:
        raise Stop("VRAM-PROBE-UNREADABLE")
    if vr < MIN_FREE_VRAM_MIB:
        raise Stop("VRAM-LOW %.0f MiB" % vr)
    os.makedirs(out + "/ticks")
    t0 = now()
    with open(out + "/argv.json", "w", encoding="utf-8") as f:
        json.dump({"arm": r["arm"], "argv": r["argv"], "start": t0}, f, indent=1)
    os.makedirs(P["logs"], exist_ok=True)
    rc = execute(r["argv"], env, out + "/t1.log", RUN_TIMEOUT_S)
    t1 = now()
    if rc != 0:
        raise Stop("ROLLOUT-RC %s %s" % (rc, r["arm"]))
    want = grid_clip_count(P[r["grid"]])
    dd = "%s/dump_%s" % (out, r["tag"])
    n = len([x for x in os.listdir(dd) if x.startswith("ep") and x.endswith(".npz")]) if os.path.isdir(dd) else 0
    if n != want:
        raise Stop("DUMP-COUNT %d expected %d %s" % (n, want, r["arm"]))
    if r["preroll"]:
        if not os.path.isfile("%s/ticks/preroll_log_%s.json" % (out, r["arm"])):
            raise Stop("NO-PREROLL-LOG %s" % r["arm"])
    if r["table"] is not None and not os.path.isfile("%s/ticks/rule_log_mid_%s.npz" % (out, r["arm"])):
        raise Stop("NO-MID-LOG %s" % r["arm"])
    if r["table"] == "zero":
        ok, cz = compare_partner(root, r)
        if not ok:
            raise Stop("CONTROL-ZERO-FAILED %s (dump files differing %d; logs %s)" % (r["arm"], len(cz["dump_bad"]), {k: v["PASS"] for k, v in cz["logs"].items()}))
        print("control zero-table PASS", r["arm"], "dump files", cz["dump_files"], "numeric arrays", cz["dump_numeric_arrays"], flush=True)
    with open(done, "w", encoding="utf-8") as f:
        json.dump({"arm": r["arm"], "rc": rc, "start": t0, "end": t1, "dump_files": n}, f)
    print("done", r["arm"], t0, t1, flush=True)


def main(argv=None):
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry", action="store_true")
    ap.add_argument("--root", default=ROOT)
    ap.add_argument("--no-sha", action="store_true", help="skip the sha256 checks (tests only)")
    ap.add_argument("--max-runs", type=int, default=0, help="run only the first N runs of the order of record, then stop with QUEUE-PAUSED")
    ap.add_argument("--ceiling", action="store_true", help="card section 3: the conditional ceiling arm H_RQ50KC1 (3 runs) instead of the main queue")
    a = ap.parse_args(argv)
    runs = build_runs(a.root, ceiling=a.ceiling)
    if a.dry:
        for i, r in enumerate(runs, 1):
            print("RUN %02d %s ckpt %s grid %s" % (i, r["arm"], r["ckpt"], r["grid"]))
            print("CMD: " + " ".join(r["argv"]))
        print("DRY: %d runs listed, nothing executed" % len(runs))
        miss = [p for p in {ckpt_path(a.root, r["ckpt"]) for r in runs} if not os.path.isfile(p)]
        print("DRY: checkpoints missing: %d" % len(miss))
        return 0
    P = paths(a.root)
    env = safe_env(a.root)
    try:
        preflight(a.root, runs, check_sha=not a.no_sha)
        if a.ceiling and free_disk_gb(a.root) < CEILING_MIN_FREE_GB:
            raise Stop("CEILING-DISK-LOW %.2f GB (card section 3: at least %.2f GB)" % (free_disk_gb(a.root), CEILING_MIN_FREE_GB))
        os.makedirs(P["runs"], exist_ok=True)
        os.makedirs(P["logs"], exist_ok=True)
        with open(P["busy"], "w", encoding="utf-8") as f:
            f.write("card ADD152 HEADCLOSE10K queue, started %s. Do NOT launch box 2 jobs while this file exists.\n" % now())
        todo = runs[:a.max_runs] if a.max_runs > 0 else runs
        for r in todo:
            run_one(a.root, r, env)
    except Stop as e:
        write_stop(P, str(e))
        return 3
    try:
        os.remove(P["busy"])
    except OSError:
        pass
    if len(todo) < len(runs):
        print("QUEUE-PAUSED after %d of %d runs" % (len(todo), len(runs)), now(), flush=True)
        return 0
    print("QUEUE-COMPLETE", now(), flush=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())
